def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]

    # The single color used for placement markers is the most common
    # non-background color.
    marker = max((v for v in counts if v != bg), key=lambda v: counts[v])
    content = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in (bg, marker)]
    if not content:
        return [row[:] for row in grid]

    r0, r1 = min(r for r, c in content), max(r for r, c in content)
    c0, c1 = min(c for r, c in content), max(c for r, c in content)
    shape = [[grid[r][c] for c in range(c0, c1 + 1)]
             for r in range(r0, r1 + 1)]

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                top, left = r - 2, c - 1
                for dr, row in enumerate(shape):
                    for dc, value in enumerate(row):
                        rr, cc = top + dr, left + dc
                        if value != bg and 0 <= rr < h and 0 <= cc < w:
                            out[rr][cc] = value
    return out
